import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"What is mealie-mcp?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1787084764000}`),a={name:`guide/index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="what-is-mealie-mcp" tabindex="-1">What is mealie-mcp? <a class="header-anchor" href="#what-is-mealie-mcp" aria-label="Permalink to “What is mealie-mcp?”">​</a></h1><p>mealie-mcp is a <a href="https://modelcontextprotocol.io" target="_blank" rel="noreferrer">Model Context Protocol</a> server for <a href="https://mealie.io" target="_blank" rel="noreferrer">Mealie</a>, the self-hosted recipe manager and meal planner. It gives a model a curated view of a Mealie instance: search and read recipes with their ingredients and steps, import new ones from a website, keep tags and categories tidy, plan meals, build shopping lists from those plans, and record what was actually cooked.</p><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>Mealie&#39;s REST API has 259 operations across 175 paths. Exposing all of them to a model would bury the useful calls under administrative noise — and hand the model routes nobody wants it to have, like backups, user management and API-token minting.</p><p>This server exposes <strong>52 tools</strong> instead, chosen so that the common tasks are one call and the dangerous surface is not reachable at all:</p><ul><li><strong>Common tasks are one call.</strong> <code>import_recipe_from_url</code> imports a recipe and returns the full result, <code>add_recipe_to_shopping_list</code> merges a recipe&#39;s ingredients into a list, <code>get_todays_meals</code> answers the obvious daily question. Recipes can be addressed by slug or by UUID everywhere — Mealie splits its identifier space between the two, and the tools resolve whichever they are given.</li><li><strong>The dangerous surface is unreachable.</strong> Everything under <code>/api/admin</code>, the token-minting route, authentication, webhooks and other outbound-HTTP triggers are simply not exposed — see <a href="/guide/security#not-exposed-on-purpose">Security</a>.</li><li><strong>Destructive calls are gated.</strong> Deletes, merges and public share links require a server-issued <a href="/guide/security#confirmation-tokens">confirmation token</a> that a model cannot fabricate.</li></ul><p>The server is verified against <strong>Mealie v3.22.0</strong>. The source of truth for every request shape is the <code>GET /openapi.json</code> of a running instance, not the published documentation, which is out of date in several places.</p><h2 id="what-it-is-not" tabindex="-1">What it is not <a class="header-anchor" href="#what-it-is-not" aria-label="Permalink to “What it is not”">​</a></h2><ul><li><strong>Not an admin tool.</strong> Backups, restore, user, group and household management, email and AI-provider settings are deliberately out of reach. Use Mealie&#39;s own web UI for those.</li><li><strong>Not a Mealie client library.</strong> The tools are shaped for a model&#39;s workflow, not as a 1:1 API mapping — several tools combine multiple API calls, and responses are trimmed and bounded so they fit a context window.</li><li><strong>Not a hosted service.</strong> It is a local stdio process started by your MCP client, talking to your Mealie instance with your token.</li></ul>`,9)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};